mapper.select:
SELECT
u.id,
u.username,
u.email,
u.phone,
u.employee_no
FROM
sys_user u


        AND u.id != #{excludeUserId}

    AND (


            OR u.username IN

                #{username}



            OR u.email IN

                #{email}



            OR u.phone IN

                #{phone}



            OR u.employee_no IN

                #{employeeNo}



    )
